class Solution {
    public int countPairs(int[] nums, int target) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] + nums[j] < target) {
                    count++;
                }
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public int countPairs(int[] nums, int target) {
        Arrays.sort(nums);
        int left = 0;
        int right = nums.length - 1;
        int count = 0;
        while (left < right) {
            if (nums[left] + nums[right] < target) {
                count += right - left;
                left++;
            } else {
                right--;
            }
        }
        return count;
    }
}

import java.util.Arrays;

class Solution {
    public int countPairs(int[] nums, int target) {
        Arrays.sort(nums);
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int limit = target - nums[i];
            int left = i + 1;
            int right = nums.length;
            while (left < right) {
                int mid = left + (right - left) / 2;
                if (nums[mid] < limit) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }
            count += left - i - 1;
        }
        return count;
    }
}

class Solution {
    public int countPairs(int[] nums, int target) {
        int[] frequency = new int[101];
        for (int value : nums) {
            frequency[value + 50]++;
        }

        int answer = 0;
        for (int a = 0; a < frequency.length; a++) {
            if (frequency[a] == 0) {
                continue;
            }
            int valueA = a - 50;
            for (int b = a; b < frequency.length; b++) {
                if (frequency[b] == 0) {
                    continue;
                }
                int valueB = b - 50;
                if (valueA + valueB >= target) {
                    continue;
                }
                if (a == b) {
                    answer += frequency[a] * (frequency[a] - 1) / 2;
                } else {
                    answer += frequency[a] * frequency[b];
                }
            }
        }
        return answer;
    }
}
